/**
 * Default Map-backed implementation of the LLMProviderRegistry contract.
 *
 * Preserves insertion order via Map (used by `list()`). Duplicate ids are
 * first-write-wins so higher-priority extensions keep their provider binding.
 *
 * @module extensions/llm/llm-provider-registry
 */
import { assertOptionalRegistrationMethod, assertRegistrationMethod, captureRegistrationId, } from "../runtime-validation.js";
class LLMProviderRegistryImpl {
    providers = new Map();
    register(provider) {
        const providerId = captureRegistrationId(provider, "LLMProvider");
        assertRegistrationMethod(provider, "LLMProvider", "createModel");
        assertOptionalRegistrationMethod(provider, "LLMProvider", "createEmbedding");
        assertOptionalRegistrationMethod(provider, "LLMProvider", "createResponses");
        if (this.providers.has(providerId)) {
            return;
        }
        this.providers.set(providerId, provider);
    }
    unregister(id) {
        this.providers.delete(id);
    }
    get(id) {
        return this.providers.get(id);
    }
    require(id) {
        const p = this.providers.get(id);
        if (p)
            return p;
        const known = [...this.providers.keys()].join(", ") || "(none)";
        throw new Error(`No LLMProvider registered for "${id}". Known providers: ${known}.`);
    }
    has(id) {
        return this.providers.has(id);
    }
    list() {
        return [...this.providers.values()];
    }
}
/** Create llmprovider registry. */
export function createLLMProviderRegistry() {
    return new LLMProviderRegistryImpl();
}
